import { createRequire } from 'module';
import { EmptyError, fromEvent, lastValueFrom, merge } from 'rxjs';
import { first, map, share, tap } from 'rxjs/operators';
import { ECONNREFUSED, ENOTFOUND, MQTT_DEFAULT_URL } from '../constants.js';
import { MqttRecord, } from '../record-builders/mqtt.record-builder.js';
